+                    GetFlamegraphResponse flamegraphResponse = buildFlamegraph(response);
+                    log.debug(
+                        "getFlamegraphAction took ["
+                            + (System.nanoTime() - start) / 1_000_000.0d
+                            + "] ms (processing response: ["
+                            + (System.nanoTime() - responseStart) / 1_000_000.0d
