+                    if (builder.isExists(frameGroupId)) {
+                        nodeId = builder.getNodeId(frameGroupId);
+                        builder.addSamplesInclusive(nodeId, samples);
+                    } else {
+                        nodeId = builder.addNode(
+                            fileId,
+                            frameType,
+                            frame.inline(),
+                            executable,
+                            addressOrLine,
+                            frame.functionName(),
+                            frame.functionOffset(),
+                            frame.fileName(),
+                            frame.lineNumber(),
+                            samples,
+                            frameGroupId
