+    public APMMeter(Settings settings, Supplier<Meter> otelMeterSupplier, Supplier<Meter> noopMeterSupplier) {
+        this.enabled = TELEMETRY_METRICS_ENABLED_SETTING.get(settings);
+        this.otelMeterSupplier = otelMeterSupplier;
