+        } else {
+            instruments.setProvider(createNoopMeter());
+        }
+    }
+
+    @Override
+    protected void doStart() {}
+
+    @Override
+    protected void doStop() {
+        instruments.setProvider(createNoopMeter());
+    }
+
+    @Override
